// The type chart (modern, 18 types, the same for every region: plan.md §4.5). Generated by scripts/build-data.mjs.

import typeData from './generated/types.json';

export const TYPES: readonly string[] = typeData.types;

const chart = typeData.chart as Record<string, Record<string, number>>;

/** Damage multiplier of an attack type against a Pokémon's types (both types multiply: 0, ¼, ½, 1, 2 or 4). */
export function effectiveness(attackType: string, defenderTypes: readonly string[]): number {
  return defenderTypes.reduce((multiplier, defending) => multiplier * (chart[attackType]?.[defending] ?? 1), 1);
}
